import json, os, re, sys
from pathlib import Path

SENSITIVE_FILE_PATTERNS = (
    r"(^|/)\.env(\..*)?$",
    r"\.(pem|key|p12|pfx)$",
    r"(^|/)(id_rsa|id_ed25519|credentials\.json|secrets\.ya?ml)$",
)
SENSITIVE_BASH_PATTERNS = (
    r"\b(printenv|env|export\s+-p|set)\b",
    r"\b(cat|head|tail|less|grep|rg|sed|awk|base64)\b[^\n]*(\.env|\.pem|secret|credentials)",
    r"echo\s+\$[A-Z0-9_]*(TOKEN|SECRET|KEY|PASSWORD|DATABASE_URL)",
)
SECRET_VALUE_REGEXES = [
    re.compile(r"(Bearer\s+)[A-Za-z0-9._\-]{16,}", re.IGNORECASE),
    re.compile(r"\bEAA[A-Za-z0-9]{20,}\b"),          # Meta Graph / CAPI Token
    re.compile(r"\bsk-(proj-|ant-)?[A-Za-z0-9_\-]{20,}\b"),  # LLM Keys
    re.compile(r"(?i)(misa_secret|oa_secret|api_key|client_secret)\s*[:=]\s*['\"]?[^\s'\"]{8,}"),
]

def evaluate_pretooluse_hook(payload: dict) -> dict | None:
    tool_name = payload.get("tool_name", "")
    tool_input = payload.get("tool_input", {}) or {}
    target_path = str(tool_input.get("file_path") or tool_input.get("path") or "").replace("\\", "/")

    if tool_name in {"Read", "Edit", "Write", "MultiEdit", "Grep"} and target_path:
        if not target_path.endswith((".env.example", ".env.template")):
            if any(re.search(p, target_path, re.IGNORECASE) for p in SENSITIVE_FILE_PATTERNS):
                return {
                    "hookSpecificOutput": {
                        "hookEventName": "PreToolUse",
                        "permissionDecision": "deny",
                        "permissionDecisionReason": (
                            f"SECURITY_POLICY: Cấm AI Agent đọc/sửa '{Path(target_path).name}'. "
                            "Hãy dùng .env.example để xem tên biến hoặc gọi qua Credential Broker."
                        ),
                    }
                }

    if tool_name == "Bash":
        cmd = str(tool_input.get("command") or "")
        if any(re.search(p, cmd, re.IGNORECASE) for p in SENSITIVE_BASH_PATTERNS):
            return {
                "hookSpecificOutput": {
                    "hookEventName": "PreToolUse",
                    "permissionDecision": "deny",
                    "permissionDecisionReason": "SECURITY_POLICY: Lệnh shell có dấu hiệu trích xuất biến môi trường hoặc tệp Secret.",
                }
            }
    return None

def scrub_secrets_for_trace(text: str) -> str:
    cleaned = text or ""
    for rx in SECRET_VALUE_REGEXES:
        cleaned = rx.sub("[REDACTED_SECRET]", cleaned)
    return cleaned

# Mẫu ánh xạ Credential Broker chạy ở tiến trình cô lập (Agent chỉ truyền cred_ref)
ALLOWED_BROKER_ROUTES = {
    "meta_insights_ro": {"host": "graph.facebook.com", "methods": {"GET"}, "vault_env": "VAULT_META_RO_TOKEN"},
    "misa_invoice_sync": {"host": "amisapp.misa.vn", "methods": {"GET", "POST"}, "vault_env": "VAULT_MISA_SECRET"},
}

def build_broker_outbound_headers(cred_ref: str, method: str) -> dict:
    policy = ALLOWED_BROKER_ROUTES.get(cred_ref)
    if not policy or method.upper() not in policy["methods"]:
        raise PermissionError(f"Blocked broker call for ref={cred_ref}, method={method}")
    # Giải mã từ Vault ngoài bộ nhớ LLM vào phút chót trước khi gọi HTTP
    raw_token = os.environ[policy["vault_env"]]
    return {"Authorization": f"Bearer {raw_token}", "Content-Type": "application/json"}

if __name__ == "__main__":
    hook_req = json.loads(sys.stdin.read() or "{}")
    decision = evaluate_pretooluse_hook(hook_req)
    if decision:
        print(json.dumps(decision, ensure_ascii=False))
    sys.exit(0)
